<?php
// PHP 7.4+, OpenSSL. SMTP credentials are configured on the server, never in HTML.
function result($code,$message){http_response_code($code);header('Cache-Control: no-store');if(strpos($_SERVER['HTTP_ACCEPT']??'','application/json')!==false){header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>$code===200,'message'=>$message],JSON_UNESCAPED_UNICODE);}else{header('Content-Type: text/html; charset=utf-8');echo '<!doctype html><html lang="hr"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="style.css"><main><section><h1>'.htmlspecialchars($message,ENT_QUOTES,'UTF-8').'</h1><a href="index.html">Povratak na početnu</a></section></main></html>';}exit;}
if(($_SERVER['REQUEST_METHOD']??'')!=='POST')result(405,'Koristite obrazac na stranici.');
if((int)($_SERVER['CONTENT_LENGTH']??0)>32000)result(413,'Poruka je prevelika.');
function val($k){$v=$_POST[$k]??'';return is_string($v)?trim($v):'';}
$kinds=['knjigovodstvo'=>'Ponuda za knjigovodstvo','tehnika'=>'Upit za tehničke usluge','karijera'=>'Prijava za posao','kontakt'=>'Opći upit'];
$kind=val('vrsta');if(!isset($kinds[$kind])||val('website')!=='')result(400,'Neispravan obrazac.');
$email=val('email');$name=val('ime');if(!$name||strlen($name)>200||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>200||preg_match('/[\r\n]/',$email))result(400,'Provjerite ime i e-mail.');
$fields=['ime'=>'Ime i prezime','email'=>'E-mail','telefon'=>'Telefon','tvrtka'=>'Tvrtka','zaposleni'=>'Broj zaposlenika','racuni'=>'Broj računa','paket'=>'Paket','lokacija'=>'Lokacija','usluga'=>'Usluga','odjel'=>'Odjel','radno_mjesto'=>'Radno mjesto','poruka'=>'Poruka'];
$required=['knjigovodstvo'=>['tvrtka','zaposleni','racuni','paket'],'tehnika'=>['lokacija','usluga','poruka'],'karijera'=>['odjel','poruka'],'kontakt'=>['poruka']];foreach($required[$kind] as $key){if(val($key)==='')result(400,'Ispunite sva obavezna polja.');}
if($kind==='knjigovodstvo'&&filter_var(val('zaposleni'),FILTER_VALIDATE_INT,['options'=>['min_range'=>0]])===false)result(400,'Provjerite broj zaposlenika.');
$body=$kinds[$kind]."\r\n\r\n";foreach($fields as $key=>$label){$v=val($key);if(strlen($v)>($key==='poruka'?16000:800))result(400,'Unos je predugačak.');if($v!=='')$body.=$label.': '.$v."\r\n";}
// Configure SMTP using environment variables, or a PHP config file outside the public directory.
$configPath=dirname(__DIR__).'/immanis-smtp.php';$cfg=is_file($configPath)?require $configPath:[];
$host=$cfg['host']??(getenv('IMMANIS_SMTP_HOST')?:'mail.privateemail.com');$port=(int)($cfg['port']??getenv('IMMANIS_SMTP_PORT')?:587);$user=$cfg['user']??(getenv('IMMANIS_SMTP_USER')?:'info@immanis-usluge.com');$pass=$cfg['pass']??getenv('IMMANIS_SMTP_PASS');$from=$cfg['from']??$user;
if(!$host||!$user||!$pass||!filter_var($from,FILTER_VALIDATE_EMAIL)||!in_array($port,[465,587],true))result(503,'Automatska dostava još nije aktivirana.');
session_start();if(time()-($_SESSION['last_submit']??0)<30){session_write_close();result(429,'Pričekajte 30 sekundi prije ponovnog slanja.');}$_SESSION['last_submit']=time();session_write_close();
function smtp_read($s,$expected){$line='';do{$line=fgets($s,4096);if($line===false)throw new RuntimeException('SMTP response');}while(isset($line[3])&&$line[3]==='-');if(!in_array((int)substr($line,0,3),(array)$expected,true))throw new RuntimeException('SMTP rejected');}
function smtp_cmd($s,$line,$expected){if(fwrite($s,$line."\r\n")===false)throw new RuntimeException('SMTP write');smtp_read($s,$expected);}
try{$context=stream_context_create(['ssl'=>['verify_peer'=>true,'verify_peer_name'=>true,'peer_name'=>$host]]);$s=@stream_socket_client(($port===465?'tls://':'tcp://').$host.':'.$port,$errno,$errstr,12,STREAM_CLIENT_CONNECT,$context);if(!$s)throw new RuntimeException('SMTP connect');stream_set_timeout($s,12);smtp_read($s,220);smtp_cmd($s,'EHLO immanis-usluge.com',250);if($port===587){smtp_cmd($s,'STARTTLS',220);if(!stream_socket_enable_crypto($s,true,STREAM_CRYPTO_METHOD_TLS_CLIENT))throw new RuntimeException('TLS');smtp_cmd($s,'EHLO immanis-usluge.com',250);}smtp_cmd($s,'AUTH LOGIN',334);smtp_cmd($s,base64_encode($user),334);smtp_cmd($s,base64_encode($pass),235);smtp_cmd($s,'MAIL FROM:<'.$from.'>',250);smtp_cmd($s,'RCPT TO:<info@immanis-usluge.com>',[250,251]);smtp_cmd($s,'DATA',354);$subjects=['knjigovodstvo'=>'KNJIGOVODSTVO – Novi zahtjev za ponudu','tehnika'=>'GRIJANJE I HLAĐENJE – Novi upit','kontakt'=>'KONTAKT – Novi poslovni upit','karijera'=>val('odjel')==='Knjigovodstvo'?'ZAPOŠLJAVANJE – Knjigovodstvo':'ZAPOŠLJAVANJE – Tehnički odjel'];$subject='=?UTF-8?B?'.base64_encode($subjects[$kind]).'?=';$headers="From: IMMANIS USLUGE <{$from}>\r\nTo: info@immanis-usluge.com\r\nReply-To: {$email}\r\nSubject: {$subject}\r\nDate: ".date(DATE_RFC2822)."\r\nMIME-Version: 1.0\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n";smtp_cmd($s,$headers."\r\n".rtrim(chunk_split(base64_encode($body)))."\r\n.",250);fclose($s);}catch(Throwable $e){if(isset($s)&&is_resource($s))fclose($s);error_log('IMMANIS SMTP delivery failed');result(502,'Poslužitelj e-pošte nije potvrdio slanje.');}result(200,'Hvala! Poslužitelj e-pošte prihvatio je vašu poruku.');
